"use strict";(globalThis.webpackChunkelemental_selenium||=[]).push([[28206],{86244(e){e.exports=JSON.parse('{"tag":{"label":"bidi","permalink":"/tips/tags/bidi","allTagsPath":"/tips/tags","count":6,"items":[{"id":"blocklist/66-blocklist","title":"Block Slow Third-Party Requests","description":"Pages load resources that are not relevant to the functionality we test (analytics, social widgets, ads). When they load slowly, they slow down our tests or make them fail. WebDriver BiDi lets the test block them.","permalink":"/tips/66-blocklist"},{"id":"logging/54-logging","title":"How to Capture Console Logs and JavaScript Errors","description":"A page that logs an error to the console, or throws a JavaScript error, can look fine while it is broken. With WebDriver BiDi, the test gets the console messages and the errors of the page as they happen, and can check them.","permalink":"/tips/54-logging"},{"id":"control-the-clock/37-control-the-clock","title":"How to Control the Clock","description":"Messages that hide after a minute, sessions that expire after 15 minutes, and countdowns make tests slow, since the test has to wait. The test can control the clock of the page and move it forward instead.","permalink":"/tips/37-control-the-clock"},{"id":"emulate-location/35-emulate-location","title":"How to Emulate the Location, Time Zone and Locale","description":"Pages that show content for where the user is, or format dates and numbers in the user\'s language, are hard to test from one machine. The test can tell the browser which location, time zone and locale to report.","permalink":"/tips/35-emulate-location"},{"id":"mock-network-responses/20-mock-network-responses","title":"How to Mock Network Responses","description":"A page that loads its data from an API is hard to test: the API can be slow, down, or return data that changes. The test can answer the API calls itself, with the data it chooses, and check how the page shows it.","permalink":"/tips/20-mock-network-responses"},{"id":"load-testing/48-load-testing","title":"How to Turn a Selenium Test into a Load Test","description":"Our Selenium tests already walk through the main journeys of our users. With WebDriver BiDi, a test can record the requests of a journey in a HAR file, and a load testing tool like k6 can replay them with many virtual users.","permalink":"/tips/48-load-testing"}],"unlisted":false}}')}}]);